def interval(cls, frame: _T_FRAMES, start: dt_datetime, end: dt_datetime, interval: int = 1, tz: Optional[TZ_EXPR] = None, bounds: _BOUNDS = "[)", exact: bool = False) -> Iterable[Tuple["Arrow", "Arrow"]]:
    if interval < 1:
        raise ValueError("interval has to be a positive integer")
    spanRange = iter(cls.span_range(frame, start, end, tz, bounds=bounds, exact=exact))
    yield from ((intvlStart, intvlEnd) for intvlStart, intvlEnd in spanRange if not (intvlEnd := (intvlStart, next(spanRange, (None, None)))[1]) or (interval := interval - 1))"}, {"qualname": "arrow/locales.py::Locale.describe_multi", "source": "def describe_multi(self, timeframes: Sequence[Tuple[TimeFrameLiteral, Union[int, float]]], only_distance: bool = False) -> str:
    parts = [self._format_timeframe(tf, trunc(d)) for tf, d in timeframes]
    if self.and_word:
        parts.insert(-1, self.and_word)
    humanized = " ".join(parts)
    if not only_distance:
        timeframe_value = next((trunc(d) for _, d in timeframes if trunc(d)), 0)
        humanized = self._format_relative(humanized, "seconds", timeframe_value)
    return humanized"}]}
